INSERT INTO public.jobapplication (dateapplication, status, id_employment, id_user) SELECT NOW() - INTERVAL '2 days', 'PENDING', (SELECT e.id FROM public.employment e WHERE e.title = 'Frontend Jr.' AND e.id_company = (SELECT id FROM public.company WHERE username = 'company')), (SELECT id FROM public."user" WHERE username = 'developer') WHERE NOT EXISTS (SELECT 1 FROM public.jobapplication WHERE id_employment = (SELECT e.id FROM public.employment e WHERE e.title = 'Frontend Jr.' AND e.id_company = (SELECT id FROM public.company WHERE username = 'company')) AND id_user = (SELECT id FROM public."user" WHERE username = 'developer'));
INSERT INTO public.jobapplication (dateapplication, status, id_employment, id_user) SELECT NOW() - INTERVAL '5 days', 'ACCEPTED', (SELECT e.id FROM public.employment e WHERE e.title = 'Frontend Jr.' AND e.id_company = (SELECT id FROM public.company WHERE username = 'company')), (SELECT id FROM public."user" WHERE username = 'ana.torres') WHERE NOT EXISTS (SELECT 1 FROM public.jobapplication WHERE id_employment = (SELECT e.id FROM public.employment e WHERE e.title = 'Frontend Jr.' AND e.id_company = (SELECT id FROM public.company WHERE username = 'company')) AND id_user = (SELECT id FROM public."user" WHERE username = 'ana.torres'));
INSERT INTO public.jobapplication (dateapplication, status, id_employment, id_user) SELECT NOW() - INTERVAL '1 days', 'PENDING', (SELECT e.id FROM public.employment e WHERE e.title = 'Practicante de desarrollo' AND e.id_company = (SELECT id FROM public.company WHERE username = 'andes.software')), (SELECT id FROM public."user" WHERE username = 'luis.quispe') WHERE NOT EXISTS (SELECT 1 FROM public.jobapplication WHERE id_employment = (SELECT e.id FROM public.employment e WHERE e.title = 'Practicante de desarrollo' AND e.id_company = (SELECT id FROM public.company WHERE username = 'andes.software')) AND id_user = (SELECT id FROM public."user" WHERE username = 'luis.quispe'));
INSERT INTO public.jobapplication (dateapplication, status, id_employment, id_user) SELECT NOW() - INTERVAL '7 days', 'REFUSE', (SELECT e.id FROM public.employment e WHERE e.title = 'Backend Jr.' AND e.id_company = (SELECT id FROM public.company WHERE username = 'company')), (SELECT id FROM public."user" WHERE username = 'luis.quispe') WHERE NOT EXISTS (SELECT 1 FROM public.jobapplication WHERE id_employment = (SELECT e.id FROM public.employment e WHERE e.title = 'Backend Jr.' AND e.id_company = (SELECT id FROM public.company WHERE username = 'company')) AND id_user = (SELECT id FROM public."user" WHERE username = 'luis.quispe'));
